window.CURIO_TRIAL={"activities": {"act.quiz.balance-track-01": {"age_band": "G3-4", "body": {"items": [{"answer": {"choices": [{"correct": true, "id": "a", "text": "0 牛"}, {"feedback": "向左的拉力没有跟向右的拉力站在同一边。", "id": "b", "misconception": "add-both", "text": "向右 10 牛"}, {"feedback": "向右的拉力和向左的一样大。", "id": "c", "misconception": "add-both", "text": "向左 10 牛"}], "type": "choice"}, "feedback": {"correct": "把两张相反的箭头首尾接好，箭尖恰好回到起点，水平合力为零。", "wrong": "把两根一样长的箭头摆成题里给的方向。"}, "hints": ["把两根一样长的箭头摆成题里给的方向。", "让后一根从前一根的箭尖出发，看最后离起点多远。"], "id": "q1", "stem": "水平轨道上，小车受向右 5 牛和向左 5 牛的两股拉力，没有其他水平力。小车的水平合力是多少？"}, {"answer": {"common_wrong": [{"feedback": "只有相向的拉力才要比差。这次两个人都向右拉。", "misconception": "add-both", "value": 3}], "tolerance": 0, "type": "number", "unit": "牛", "value": 11}, "feedback": {"correct": "两个箭头都朝右，可以首尾接起来。向右的合力是 4 + 7 = 11 牛。", "wrong": "先检查两个人拉的是不是同一辆车。"}, "hints": ["先检查两个人拉的是不是同一辆车。", "把两个箭头照原方向接起来。"], "id": "q2", "stem": "小车水平方向只受两股力，两人都向右拉，一人用 4 牛，另一人用 7 牛。向右的合力有几牛？"}, {"answer": {"choices": [{"feedback": "车正在向左走，拉得更用力的一侧却在右方。", "id": "a", "misconception": "add-both", "text": "向左 4 牛"}, {"feedback": "先让相反方向的力各抵掉同样多，再看哪边剩下。", "id": "b", "misconception": "add-both", "text": "向右 10 牛"}, {"correct": true, "id": "c", "text": "向右 4 牛"}], "type": "choice"}, "feedback": {"correct": "向左的 3 牛抵去向右力的一部分，剩下向右 4 牛。车速方向不用加进力的账。", "wrong": "把小车运动的箭头先盖起来。"}, "hints": ["把小车运动的箭头先盖起来。", "两根拉绳对车的力抵掉相等部分后，看剩下哪一头。"], "id": "q3", "stem": "车正向左滑。水平力只有拉绳向右的 7 牛和另一根绳向左的 3 牛。哪张水平合力标签该贴在车上？"}, {"answer": {"common_wrong": [{"feedback": "右边已经有一根绳在帮忙，只需补上缺的那部分。", "misconception": "add-both", "value": 13}], "tolerance": 0, "type": "number", "unit": "牛", "value": 5}, "feedback": {"correct": "右边两根合计要有 9 牛。已有 4 牛，另一根需要 9 − 4 = 5 牛。", "wrong": "把向右的两根绳记在同一栏。"}, "hints": ["把向右的两根绳记在同一栏。", "看看右栏还缺多少才能和左栏一样大。"], "id": "q4", "stem": "轨道车受一个向左的 9 牛拉力，其他水平力只有右边的两根拉绳。一根向右拉 4 牛，另一根向右拉几牛才能让水平合力为零？"}, {"answer": {"choices": [{"feedback": "原先两根绳合起来已偏向右，再向右拉会更不平衡。", "id": "a", "misconception": "add-both", "text": "向右拉 5 牛"}, {"correct": true, "id": "b", "text": "向左拉 5 牛"}, {"feedback": "两根绳原来方向相反。先比较它们各自还剩多少。", "id": "c", "misconception": "add-both", "text": "向左拉 11 牛"}], "type": "choice"}, "feedback": {"correct": "先合成向右 5 牛，再用向左 5 牛抵消。合力为零，车可以保持原来的速度。", "wrong": "先把已挂的两根绳合成一个箭头。"}, "hints": ["先把已挂的两根绳合成一个箭头。", "让新绳和这个箭头接起来，看看能否回到起点。"], "id": "q5", "stem": "车正匀速向左滑。此刻挂上向右 8 牛和向左 3 牛的拉绳，其他水平力可忽略。要让车继续按原速度滑，第三根绳应怎样拉？"}], "shuffle": false}, "duration_min": 7, "id": "act.quiz.balance-track-01", "kind": "quiz", "targets": ["p.g8.force"], "title": "给小车配力箭头"}, "act.quiz.energy-dock-01": {"age_band": "G3-4", "body": {"items": [{"answer": {"choices": [{"feedback": "滑块正在下降并且加速。", "id": "a", "misconception": "stopped-is-gone", "text": "势能增加，动能减少"}, {"feedback": "变快的滑块会占用更多动能格。", "id": "b", "misconception": "stopped-is-gone", "text": "势能减少，动能也减少"}, {"correct": true, "id": "c", "text": "势能减少，动能增加"}], "type": "choice"}, "feedback": {"correct": "滑块在下降，重力势能格减少。它越跑越快，动能格增加。", "wrong": "先看滑块离坡底的高度。"}, "hints": ["先看滑块离坡底的高度。", "再比较滑块在同样长时间内走过的路。"], "id": "q1", "stem": "滑块从坡顶静止滑下，轨道光滑。把滑块、轨道和地球一起算，忽略空气阻力及声音。滑块还在半坡，哪两栏该一起改？"}, {"answer": {"common_wrong": [{"feedback": "刚松手时速度为零，到这个位置时滑块已经在动。", "misconception": "stopped-is-gone", "value": 0}], "tolerance": 0, "type": "number", "unit": "焦", "value": 14}, "feedback": {"correct": "势能减去的 14 焦都转成了动能。滑块此刻有 14 焦动能。", "wrong": "圈起坡顶那个刚松手的时刻。"}, "hints": ["圈起坡顶那个刚松手的时刻。", "把高度下降时移出的格子，填到加速的那一栏。"], "id": "q2", "stem": "滑块从静止沿光滑坡下滑。滑块与地球的重力势能少了 14 焦。忽略转动、空气阻力，没有其他能量交换。滑块的动能是几焦？"}, {"answer": {"choices": [{"correct": true, "id": "a", "text": "滑块和垫的内能"}, {"feedback": "垫子是水平的，滑块没有升到更高的地方。", "id": "b", "misconception": "stopped-is-gone", "text": "重力势能"}, {"feedback": "把滑块和垫都圈进去，再找摩擦带来的变化。", "id": "c", "misconception": "stopped-is-gone", "text": "没有一栏增加"}], "type": "choice"}, "feedback": {"correct": "摩擦让接触处的内能增加。滑块停下来后，这些格子仍留在系统的账本里。", "wrong": "沿水平垫看看滑块的高度变没变。"}, "hints": ["沿水平垫看看滑块的高度变没变。", "手指搓一搓，留意接触处有什么变化。"], "id": "q3", "stem": "滑块进入粗糙的水平垫，慢慢停下。把滑块、垫和地球一起算，没有能量传到外面，忽略声音。动能栏清空时，哪一栏会增加？"}, {"answer": {"common_wrong": [{"feedback": "滑块还留有一部分动能，并没有全部滑停。", "misconception": "stopped-is-gone", "value": 15}], "tolerance": 0, "type": "number", "unit": "焦", "value": 6}, "feedback": {"correct": "从动能栏移出的 15 − 9 = 6 焦，进了滑块和垫的内能栏。", "wrong": "看看滑块走到这里时动能栏还剩多少。"}, "hints": ["看看滑块走到这里时动能栏还剩多少。", "用刚上垫时的格数减去余下的格数。"], "id": "q4", "stem": "水平垫上，滑块的动能从 15 焦变为 9 焦。把滑块和垫一起算，没有外界做功或传热，只计动能和内能。内能增加几焦？"}, {"answer": {"common_wrong": [{"feedback": "势能移出的格子中，已有一部分记入了内能。", "misconception": "stopped-is-gone", "value": 18}], "tolerance": 0, "type": "number", "unit": "焦", "value": 10}, "feedback": {"correct": "先合并两段垫的内能增量，3 + 5 = 8 焦。剩在动能栏的是 18 − 8 = 10 焦。", "wrong": "把两段垫对应的内能格先放到同一栏。"}, "hints": ["把两段垫对应的内能格先放到同一栏。", "从势能移出的总量里扣掉这一栏，再看滑块还带着多少。"], "id": "q5", "stem": "滑块从静止滑下。滑块、垫和地球无能量进出，只计势能、动能和内能。势能少了 18 焦，两段垫分别使内能增加 3 焦和 5 焦。滑块还有几焦动能？"}], "shuffle": false}, "duration_min": 7, "id": "act.quiz.energy-dock-01", "kind": "quiz", "targets": ["physics.energy.transfer"], "title": "沿轨道追能量"}, "act.quiz.glide-track-01": {"age_band": "G3-4", "body": {"items": [{"answer": {"choices": [{"feedback": "松手取消了推力，此刻的速度还在。", "id": "a", "misconception": "keep-pushing", "text": "立刻停住"}, {"correct": true, "id": "b", "text": "按原速度继续向右"}, {"feedback": "松手后没有水平合力使它继续加速。", "id": "c", "misconception": "keep-pushing", "text": "继续向右加快"}], "type": "choice"}, "feedback": {"correct": "车已经在向右走，松手后水平合力为零，车保持原来的速度。", "wrong": "分开看手还碰着车和手已离开这两个时刻。"}, "hints": ["分开看手还碰着车和手已离开这两个时刻。", "只看手离开之后，有谁能改变它的水平速度。"], "id": "q1", "stem": "光滑水平轨道上，手给车向右一推就松开。之后没有水平外力。松手时车还在动，下一秒会怎样？"}, {"answer": {"common_wrong": [{"feedback": "手离开时小车仍在动，接下来的每秒仍会前进。", "misconception": "keep-pushing", "value": 0}], "tolerance": 0, "type": "number", "unit": "米", "value": 12}, "feedback": {"correct": "每秒的距离保持 3 米，四段相连正好走 12 米。", "wrong": "把记录带剪成同样长的时间段。"}, "hints": ["把记录带剪成同样长的时间段。", "先填好每段的路程，再把各段相加。"], "id": "q2", "stem": "在一段水平直轨上，小车向右滑，每秒走 3 米。它离开手后不受水平外力。接下来 4 秒一共向右走几米？"}, {"answer": {"choices": [{"correct": true, "id": "a", "text": "车受到向左的摩擦力"}, {"feedback": "若水平合力为零，每秒印出的间距应相等。", "id": "b", "misconception": "keep-pushing", "text": "松手后所有力都消失了"}, {"feedback": "车向右时受向右的合力，在相同时间里会走得越来越远。", "id": "c", "misconception": "keep-pushing", "text": "车受到向右的合力"}], "type": "choice"}, "feedback": {"correct": "点越密，同样一秒走得越少。向左的摩擦力能让向右滑的车减速。", "wrong": "先比较两对相邻点的间距。"}, "hints": ["先比较两对相邻点的间距。", "找一个能使向右速度变小的力的方向。"], "id": "q3", "stem": "一辆车松手后向右滑进粗糙水平垫。打点器每秒印一点，车还在向右走，但相邻点越来越近。哪一项能解释这串点？"}, {"answer": {"common_wrong": [{"feedback": "向右运动可以在水平合力为零时继续。", "misconception": "keep-pushing", "value": 0}], "tolerance": 0, "type": "number", "unit": "米", "value": 12}, "feedback": {"correct": "从前一段读出每秒 8 ÷ 2 = 4 米。后面三秒仍走 4 × 3 = 12 米。", "wrong": "把前一段的距离均分给每一秒。"}, "hints": ["把前一段的距离均分给每一秒。", "按同样的每秒距离延长纸带。"], "id": "q4", "stem": "一辆车以不变的速度向右滑行，水平方向可能有拉力和阻力。它在 2 秒里走了 8 米，再保持原速走 3 秒会走几米？"}, {"answer": {"choices": [{"feedback": "如果拉力恰好抵住阻力，水平合力也为零。", "id": "a", "misconception": "keep-pushing", "text": "只有甲说的能"}, {"feedback": "即使根本没有水平力，原本在运动的车仍会向前。", "id": "b", "misconception": "keep-pushing", "text": "只有乙说的能"}, {"correct": true, "id": "c", "text": "两种都能"}], "type": "choice"}, "feedback": {"correct": "两种情形的水平合力都为零，都能让速度保持。只看这些车印，分不出是哪一种。", "wrong": "相邻车印之间的时间相等，先读出车速有没有变。"}, "hints": ["相邻车印之间的时间相等，先读出车速有没有变。", "分别把甲、乙描述的水平力合起来，再对照车印。"], "id": "q5", "stem": "车沿直轨向右匀速滑，等时车印间距相同。甲说车没有水平力，乙说向右拉力与向左阻力相等。这两种情况，哪些能留下这样的车印？"}], "shuffle": false}, "duration_min": 7, "id": "act.quiz.glide-track-01", "kind": "quiz", "targets": ["physics.motion.inertia"], "title": "读轨道上的车印"}, "act.quiz.lever-dock-01": {"age_band": "G3-4", "body": {"items": [{"answer": {"choices": [{"correct": true, "id": "a", "text": "右头先低"}, {"feedback": "两边确实各两牛。右边的两牛，挂在了第三孔。", "id": "b", "misconception": "equal-loads", "text": "两头一样高"}], "type": "choice"}, "feedback": {"correct": "两边挂得一样重，你还看了孔。右钩离木尖更远，右头先低。", "wrong": "要让一样重的两端停平，两钩还得离木尖一样远。"}, "figure": {"src": "content/assets/physics.machine.lever/before-release.svg", "type": "svg"}, "hints": ["用手指从三角木分别走到两个钩。"], "id": "q1", "stem": "牛是力的单位。木杆两头各挂 2 牛。左钩离三角木 1 格，右钩 3 格。把杆放平再松手，会怎样？"}, {"answer": {"choices": [{"feedback": "左钩挂着五牛。右钩虽只有两牛，每牛却能盖三枚印。", "id": "a", "misconception": "heavy-wins", "text": "左边先低"}, {"correct": true, "id": "b", "text": "右边先低"}], "type": "choice"}, "feedback": {"correct": "左钩盖了五枚印，右钩盖了六枚。右头先低。", "wrong": "左钩离木尖只有一格。右钩的两牛各盖三枚印，得把它们合在一块儿数。"}, "hints": ["给左边的每牛盖一枚印，再给右边的每牛盖三枚。"], "id": "q2", "stem": "这回左钩挂 5 牛，离木尖 1 格。右钩挂 2 牛，离木尖 3 格。杆放平再松手，哪头先低？"}, {"answer": {"choices": [{"feedback": "右钩确实远。它的两排只有六枚印，左边的五排一共有十枚。", "id": "a", "misconception": "far-wins", "text": "更远的右头"}, {"correct": true, "id": "b", "text": "更近的左头"}], "type": "choice"}, "feedback": {"correct": "左钩离木尖近一格，可五排两枚凑成十枚，压过了右边的六枚。", "wrong": "右边的钩走得远，却只有两个环在那儿挂着。"}, "hints": ["给每一牛画一排，把经过的格数点进去。"], "id": "q3", "stem": "左钩在第 2 格，挂 5 牛。右钩在第 3 格，挂 2 牛。小伙伴说离木尖远的那头总会低。松开水平的杆，你押哪头？"}, {"answer": {"common_wrong": [{"feedback": "左钩的封条还在原孔，木尖已经走开一步。", "misconception": "pivot-carries-hooks", "value": 3}, {"feedback": "两格是木尖到右箱的路，你找到了另一头。", "misconception": "wrong-side", "value": 2}], "tolerance": 0, "type": "number", "unit": "格", "value": 4}, "feedback": {"correct": "原先左边留了三格。木尖朝右箱挪一步，左边那段路就多了一格。", "wrong": "从左钩起，一格一格往右数。走到新的木尖就停。"}, "hints": ["手指按住左钩，把另一根手指放在新的木尖上。"], "id": "q4", "stem": "两个挂钩钉死在杆上，相隔 6 格。两头各挂 6 牛，三角木撑在正中间。把三角木朝右箱挪 1 格。左钩现在离木尖几格？"}, {"answer": {"choices": [{"feedback": "左边留三格，挂两牛，有六枚印。右边还剩两格，四牛盖出八枚，右箱先沉。", "id": "a", "text": "左边留 3 格，挂 2 牛"}, {"feedback": "左边留四格，挂两牛，盖出八枚印。右边只有四枚。箱子抬起来了，木杆还在转。", "id": "b", "misconception": "overbalances", "text": "左边留 4 格，挂 2 牛"}, {"correct": true, "id": "c", "text": "左边留 4 格，挂 1 牛"}], "type": "choice"}, "feedback": {"correct": "你给小砝码留了四格，也给箱子留了一格。两边各四枚，木杆正好停住。", "wrong": "刚好停平的时候，两排印要一样长。"}, "hints": ["先在五格木条上点出三角木，再往左右各数一遍。", "两钩之间总共只有五格。木尖给左钩留了几格，右边还剩几格？"], "id": "q5", "stem": "修船棚的两钩相隔 5 格。右箱 4 牛，左钩只能挂 1 牛或 2 牛。从左钩到木尖，可以留 3 格或 4 格。左边留几格、挂几牛，能让杆停平？"}], "shuffle": false}, "duration_min": 7, "id": "act.quiz.lever-dock-01", "kind": "quiz", "targets": ["physics.machine.lever"], "title": "杠杆配平挑战"}, "act.quiz.pair-track-01": {"age_band": "G3-4", "body": {"items": [{"answer": {"choices": [{"feedback": "两车互推时，它们对彼此的力方向相反。", "id": "a", "misconception": "cancel-on-one", "text": "乙对甲，向右"}, {"correct": true, "id": "b", "text": "乙对甲，向左"}, {"feedback": "这是轨道托住车的力。互推的那一对来自甲、乙两车。", "id": "c", "misconception": "cancel-on-one", "text": "轨道对乙，向上"}], "type": "choice"}, "feedback": {"correct": "找到同一次接触，再交换“谁推谁”。乙推甲的力朝左。", "wrong": "找正在互相接触的两辆车。"}, "hints": ["找正在互相接触的两辆车。", "交换施力者和受力者，再核对箭头方向。"], "id": "q1", "stem": "光滑水平轨道上，甲车在左，乙车在右。甲的弹簧向右推乙。哪张标签写的是这股力的伙伴？"}, {"answer": {"common_wrong": [{"feedback": "重车也在向左推轻车，两个力分别落在两辆车上。", "misconception": "cancel-on-one", "value": 0}], "tolerance": 0, "type": "number", "unit": "牛", "value": 6}, "feedback": {"correct": "同一对相互作用力大小相等。重车反推轻车的力也是 6 牛。", "wrong": "先在两张力签上各写一辆受力的车。"}, "hints": ["先在两张力签上各写一辆受力的车。", "两张力签记录同一次接触，比较它们的大小。"], "id": "q2", "stem": "轻车在左、重车在右。轻车向右推重车，此刻轻车的弹簧秤读 6 牛。重车同时向左推轻车的力有几牛？"}, {"answer": {"choices": [{"feedback": "改方向没有解决力签贴错车的问题。", "id": "a", "misconception": "cancel-on-one", "text": "把两个箭头都改成向右"}, {"feedback": "两张力签的受力者不同。找出名字在“推”字后面的那辆车。", "id": "b", "misconception": "cancel-on-one", "text": "两张都留在甲车图上"}, {"correct": true, "id": "c", "text": "把“甲推乙”移到乙车图上"}], "type": "choice"}, "feedback": {"correct": "“甲推乙”的受力者是乙。甲的图上只能把甲受到的力相加。", "wrong": "逐张读出是谁受到了推力。"}, "hints": ["逐张读出是谁受到了推力。", "用“推”字后面的名字给每张力签选车。"], "id": "q3", "stem": "甲乙两车互推。你把“甲推乙”和“乙推甲”两张力签都放到甲的受力图上，算出零。应该怎样改？"}, {"answer": {"common_wrong": [{"feedback": "重车向左推轻车的力作用在轻车上，不能从重车的受力栏里扣掉。", "misconception": "cancel-on-one", "value": 0}], "tolerance": 0, "type": "number", "unit": "米每秒", "value": 2}, "feedback": {"correct": "重车受的水平合力向右。8 ÷ 4 = 2，每秒向右增加 2 米每秒的速度。", "wrong": "只保留落到重车上的力签。"}, "hints": ["只保留落到重车上的力签。", "用重车的水平合力除以它自己的质量。"], "id": "q4", "stem": "光滑水平轨道上，两辆车只在水平方向互推。2 千克的轻车在左，4 千克的重车在右。轻车持续向右推重车 8 牛，重车每秒向右增加多少米每秒的速度？"}, {"answer": {"choices": [{"correct": true, "id": "a", "text": "重车匀速向右，轻车受重车向左推"}, {"feedback": "重车受到的水平力平衡，原有速度会保持。", "id": "b", "misconception": "cancel-on-one", "text": "重车立刻停下，轻车受重车向左推"}, {"feedback": "绳的拉力也作用在重车上。两车接触时都会受到对方的推力。", "id": "c", "misconception": "cancel-on-one", "text": "重车向右加速，轻车没有受到推力"}], "type": "choice"}, "feedback": {"correct": "先看重车，两股力平衡，它保持向右的速度。再看互推的伙伴，重车对轻车的推力向左。", "wrong": "给重车画一张图，只放重车受到的力。"}, "hints": ["给重车画一张图，只放重车受到的力。", "再从两车的接触处找出作用在轻车上的那支箭头。"], "id": "q5", "stem": "水平直轨上，轻车从左向右推重车 4 牛，绳子同时向左拉重车 4 牛。两股力保持不变，重车原来向右滑，另无水平力。哪张记录能同时解释重车和轻车？"}], "shuffle": false}, "duration_min": 7, "id": "act.quiz.pair-track-01", "kind": "quiz", "targets": ["physics.motion.action-reaction"], "title": "给两辆车贴力签"}, "act.quiz.power-dock-01": {"age_band": "G3-4", "body": {"items": [{"answer": {"choices": [{"correct": true, "id": "a", "text": "甲车"}, {"feedback": "两车要分的功一样，乙车把它摊在更多秒里。", "id": "b", "misconception": "first-is-powerful", "text": "乙车"}, {"feedback": "工作票的焦数一样，秒表上的时间不同。", "id": "c", "misconception": "first-is-powerful", "text": "两车一样"}], "type": "choice"}, "feedback": {"correct": "甲每秒平均做 4 焦，乙每秒平均做 2 焦。甲的平均功率更大。", "wrong": "把每辆车的一趟功均分给各秒。"}, "hints": ["把每辆车的一趟功均分给各秒。", "比一比哪一格秒表分到的功多。"], "id": "q1", "stem": "两辆货车各完成 12 焦的搬运功。甲用 3 秒，乙用 6 秒。哪一辆在这趟中平均每秒做功更多？"}, {"answer": {"common_wrong": [{"feedback": "20 焦是整趟的功。平均功率要看每秒分到多少。", "misconception": "first-is-powerful", "value": 20}], "tolerance": 0, "type": "number", "unit": "瓦", "value": 5}, "feedback": {"correct": "把 20 焦均分给 4 秒，每秒平均 5 焦。这一趟的平均功率是 5 瓦。", "wrong": "一瓦表示平均每秒做一焦的功。"}, "hints": ["一瓦表示平均每秒做一焦的功。", "把总功除以秒表读数。"], "id": "q2", "stem": "小吊机在一次升货中做了 20 焦的功，正好用了 4 秒。这一趟的平均功率有几瓦？"}, {"answer": {"choices": [{"feedback": "甲也可能只搬了一个很轻的小箱，做的功较少。", "id": "a", "misconception": "first-is-powerful", "text": "一定是甲"}, {"feedback": "乙用时晚，也可能做了更大或更小的一单。", "id": "b", "misconception": "first-is-powerful", "text": "一定是乙"}, {"correct": true, "id": "c", "text": "还得读出它们的功和各自用时"}], "type": "choice"}, "feedback": {"correct": "先后顺序没有给出每秒的功。补齐两张票的焦数和耗时，才能比较。", "wrong": "想想两份订单的货可能一样重吗。"}, "hints": ["想想两份订单的货可能一样重吗。", "看看平均功率要用的两个读数是否齐了。"], "id": "q3", "stem": "甲起重机先做完，乙随后也做完。两张工票的功栏都被墨水盖住了。只凭先后，能挑出平均功率大的吗？"}, {"answer": {"common_wrong": [{"feedback": "两次用时不同，同样的平均功率会得到不同的总功。", "misconception": "first-is-powerful", "value": 18}], "tolerance": 0, "type": "number", "unit": "焦", "value": 12}, "feedback": {"correct": "第一趟平均每秒做 3 焦。保持这个平均数，4 秒做 12 焦。", "wrong": "先从第一张票找出平均每秒的功。"}, "hints": ["先从第一张票找出平均每秒的功。", "再把每秒的份额乘以下一趟的用时。"], "id": "q4", "stem": "码头吊钩在 6 秒内对一箱货做了 18 焦的功。下一趟要在 4 秒内保持同样的平均功率，这一趟应做几焦的功？"}, {"answer": {"choices": [{"feedback": "甲每秒平均做 4 焦。再核对乙的每秒读数。", "id": "a", "misconception": "first-is-powerful", "text": "贴甲，它先完工"}, {"correct": true, "id": "b", "text": "贴乙，它平均每秒多做 1 焦"}, {"feedback": "17 焦是两张票总功的差，两台的用时不同。", "id": "c", "misconception": "first-is-powerful", "text": "贴乙，它平均每秒多做 17 焦"}], "type": "choice"}, "feedback": {"correct": "甲是 8 ÷ 2 = 4 瓦，乙是 25 ÷ 5 = 5 瓦。乙晚完工，每秒却多做 1 焦。", "wrong": "先遮住两台完工的名次。"}, "hints": ["先遮住两台完工的名次。", "给每张工票分别算平均每秒的功，再比较它们的差。"], "id": "q5", "stem": "两台绞车同时开工。甲先完成小单，2 秒做 8 焦。乙后完成大单，5 秒做 25 焦。哪张“平均功率冠军”贴纸贴得对？"}], "shuffle": false}, "duration_min": 7, "id": "act.quiz.power-dock-01", "kind": "quiz", "targets": ["physics.energy.power"], "title": "给起重机打工票"}, "act.quiz.pulley-dock-01": {"age_band": "G3-4", "body": {"items": [{"answer": {"choices": [{"correct": true, "id": "a", "text": "8 牛"}, {"feedback": "轮子两旁都有绳，可直接提箱子的只有一段。", "id": "b", "misconception": "wheel-count", "text": "4 牛"}, {"feedback": "轮子改了拉绳方向，箱子并没有变重。", "id": "c", "misconception": "wheel-count", "text": "16 牛"}], "type": "choice"}, "feedback": {"correct": "跟着箱子的挂钩找，一段绳向上托它。这一段的拉力等于箱重。", "wrong": "从箱子的挂钩往上看。"}, "hints": ["从箱子的挂钩往上看。", "数真正向上提箱子的绳段。"], "id": "q1", "stem": "绳和轮都很轻，没有摩擦。绳绕过天花板上的定滑轮，一端挂 8 牛的箱子。向下匀速拉另一端，要用多大力？"}, {"answer": {"common_wrong": [{"feedback": "若每段绳都拉 10 牛，两段合起来就超过箱重了。", "misconception": "wheel-count", "value": 10}], "tolerance": 0, "type": "number", "unit": "牛", "value": 5}, "feedback": {"correct": "两段绳拉力一样，托住的总重是 10 牛。每段分到 5 牛。", "wrong": "只数直接托着动滑轮的绳段。"}, "hints": ["只数直接托着动滑轮的绳段。", "让各段绳的拉力加在一起，刚好等于箱重。"], "id": "q2", "stem": "轻动滑轮和箱子一起匀速上升。两段竖直的轻绳托着重 10 牛的箱子，不计摩擦。手拉绳头要用几牛？"}, {"answer": {"common_wrong": [{"feedback": "你只数了篮子向上走的路。轮子两边的绳都会变短。", "misconception": "wheel-count", "value": 3}], "tolerance": 0, "type": "number", "unit": "米", "value": 6}, "feedback": {"correct": "两段各缩短 3 米，手端总共收进 3 + 3 = 6 米。", "wrong": "观察会变短的绳段。"}, "hints": ["观察会变短的绳段。", "把每段缩短的长度加在一起。"], "id": "q3", "stem": "一根绷紧的绳不会伸长。两段竖直绳托着动滑轮和篮子。篮子匀速升高 3 米，手要收进几米绳？"}, {"answer": {"choices": [{"feedback": "新增的轮子固定在天花板上，没有给箱子增加承重绳段。", "id": "a", "misconception": "wheel-count", "text": "手需要的力减半"}, {"feedback": "绕行让手能朝下拉，原有两段绳仍在一起托箱子。", "id": "b", "misconception": "wheel-count", "text": "手需要的力加倍"}, {"correct": true, "id": "c", "text": "手需要的力和原来一样"}], "type": "choice"}, "feedback": {"correct": "看哪几段绳随箱子缩短，就能找到分担重量的绳段。新增的轮子只改拉绳方向。", "wrong": "跟踪新轮子挂在哪里。"}, "hints": ["跟踪新轮子挂在哪里。", "比较改绳路前后，直接向上拉动滑轮的绳段数。"], "id": "q4", "stem": "一台理想吊机有两段竖直绳托箱。再在天花板加一个定滑轮，只把绳头转向下。匀速升起同一箱子，手感怎样？"}, {"answer": {"choices": [{"feedback": "货升高时，两段承重绳都会缩短。", "id": "a", "misconception": "wheel-count", "text": "力和能拉的绳都够"}, {"correct": true, "id": "b", "text": "力够，能拉的绳不够"}, {"feedback": "比较手的力时，要先把箱重分到两段绳上。", "id": "c", "misconception": "wheel-count", "text": "绳够，手的力不够"}], "type": "choice"}, "feedback": {"correct": "每段是 6 牛，手能拉动。升高 2 米要收 4 米绳，现有行程还差 1 米。", "wrong": "给手力和可拉绳长各画一个勾选框。"}, "hints": ["给手力和可拉绳长各画一个勾选框。", "先用箱重除以段数，再用升高量乘段数，分别核对。"], "id": "q5", "stem": "两段竖直绳托着理想动滑轮。箱重 12 牛，要匀速升高 2 米。手能拉 7 牛，绳头只剩 3 米可拉。能到吗？"}], "shuffle": false}, "duration_min": 7, "id": "act.quiz.pulley-dock-01", "kind": "quiz", "targets": ["physics.machine.pulley"], "title": "给吊箱选绳路"}, "act.quiz.push-track-01": {"age_band": "G3-4", "body": {"items": [{"answer": {"choices": [{"feedback": "甲虽然开得快，但纸带上它的速度读数一直相同。", "id": "a", "misconception": "speed-is-acceleration", "text": "甲车"}, {"feedback": "试着给每辆车的后一格读数减去前一格。", "id": "b", "misconception": "speed-is-acceleration", "text": "两车都在加速"}, {"correct": true, "id": "c", "text": "乙车"}], "type": "choice"}, "feedback": {"correct": "乙每过一秒就多出每秒 2 米的速度。甲的读数从头到尾没有变。", "wrong": "快慢先看每张读数，变化要看相邻两张。"}, "hints": ["快慢先看每张读数，变化要看相邻两张。", "在同一辆车的读数之间标出增加量。"], "id": "q1", "stem": "打点器每秒记一次向右的车速。甲车三次都是每秒 6 米。乙车三次依次是每秒 1、3、5 米。哪辆在加速？"}, {"answer": {"common_wrong": [{"feedback": "推同样的力还得看被推的总质量。", "misconception": "speed-is-acceleration", "value": 12}], "tolerance": 0, "type": "number", "unit": "米每秒", "value": 4}, "feedback": {"correct": "12 牛除以 3 千克，算出向右的加速度。每过一秒，速度向右增加 4 米每秒。", "wrong": "圈出合力和带货的总质量。"}, "hints": ["圈出合力和带货的总质量。", "把合力除以总质量，就能读到每秒的速度变化。"], "id": "q2", "stem": "总质量为 3 千克的车在水平直轨上受向右 12 牛的恒定合力。每过一秒，它的速度向右增加多少米每秒？"}, {"answer": {"choices": [{"correct": true, "id": "a", "text": "调到 12 牛"}, {"feedback": "同样的合力推更重的车，每秒的速度变化会更小。", "id": "b", "misconception": "speed-is-acceleration", "text": "也用 6 牛"}, {"feedback": "车更重又减小推力，每秒的速度变化会更小。", "id": "c", "misconception": "speed-is-acceleration", "text": "调到 3 牛"}], "type": "choice"}, "feedback": {"correct": "乙车的质量是甲的两倍，合力也要加倍。两次合力除以质量都相同。", "wrong": "先比较两辆车的总质量。"}, "hints": ["先比较两辆车的总质量。", "让合力和质量按照相同的倍数一起变动。"], "id": "q3", "stem": "同一起点放两辆静止车。甲车总质量 2 千克，乙车 4 千克。甲受向右 6 牛恒定合力。乙车要和甲每秒加快得一样多，向右合力应怎样调？"}, {"answer": {"common_wrong": [{"feedback": "5 来自把两个力相加。阻力与拉绳方向相反。", "misconception": "speed-is-acceleration", "value": 5}], "tolerance": 0, "type": "number", "unit": "米每秒", "value": 2}, "feedback": {"correct": "先求向右合力 14 − 6 = 8 牛。再除以 4 千克，每过一秒向右增加 2 米每秒。", "wrong": "先把车身上相反方向的力合成一个。"}, "hints": ["先把车身上相反方向的力合成一个。", "再把合力平均分给车的总质量。"], "id": "q4", "stem": "一辆满载车总质量 4 千克。水平拉绳向右用 14 牛，阻力向左为 6 牛，两个力都恒定。每秒车速向右增加多少米每秒？"}, {"answer": {"choices": [{"feedback": "车速指向右，合力已经改向左。加速度跟着合力。", "id": "a", "misconception": "speed-is-acceleration", "text": "加速度向右，车继续加快"}, {"correct": true, "id": "b", "text": "加速度向左，车暂时变慢"}, {"feedback": "向左的力会先减小原有的向右速度，车不会立即反向。", "id": "c", "misconception": "speed-is-acceleration", "text": "加速度向左，车立刻向左加快"}], "type": "choice"}, "feedback": {"correct": "看合力判出加速度向左。它与原来的速度反向，先让向右的速度减小。", "wrong": "先只看力的箭头，判断加速度方向。"}, "hints": ["先只看力的箭头，判断加速度方向。", "再把这个方向和车原先的行驶方向比较。"], "id": "q5", "stem": "一辆 2 千克小车正向右滑。此刻水平合力变为向左 4 牛，并保持不变。刚开始、还没停住时，车的加速度和快慢怎样变？"}], "shuffle": false}, "duration_min": 7, "id": "act.quiz.push-track-01", "kind": "quiz", "targets": ["physics.motion.force-acceleration"], "title": "给加速小车选推杆"}, "act.quiz.ramp-dock-01": {"age_band": "G3-4", "body": {"items": [{"answer": {"choices": [{"feedback": "两块板的上端都靠在同一站台边。", "id": "a", "misconception": "length-is-height", "text": "路和高度都变大"}, {"feedback": "沿着较长的板量，箱子走的路会变长。", "id": "b", "misconception": "length-is-height", "text": "路和高度都相同"}, {"correct": true, "id": "c", "text": "路变长，高度相同"}], "type": "choice"}, "feedback": {"correct": "你分别看了坡面和竖直高度尺。两块板绕了不同长的路，却到达同一层。", "wrong": "先找箱子最后停在哪一层。"}, "hints": ["先找箱子最后停在哪一层。", "再让手指沿坡板从脚走到顶。"], "id": "q1", "stem": "同一只箱子沿光滑直坡匀速上同一站台，手沿坡推。短板换成长板。箱子走的路和升高的高度怎样变？"}, {"answer": {"common_wrong": [{"feedback": "竖直抬箱时用箱重作力。沿坡推时可以多走些路。", "misconception": "length-is-height", "value": 12}], "tolerance": 0, "type": "number", "unit": "牛", "value": 4}, "feedback": {"correct": "升高箱子需要 12 焦，分到 3 米坡路上，沿坡只需用 4 牛的力推。", "wrong": "算一算把货升到这个高度要做多少功。"}, "hints": ["算一算把货升到这个高度要做多少功。", "把这份功均分到沿坡推过的路程上。"], "id": "q2", "stem": "箱重 12 牛，沿光滑坡板匀速升高 1 米。坡板长 3 米。沿坡推它的手需要用几牛？"}, {"answer": {"choices": [{"correct": true, "id": "a", "text": "一样多"}, {"feedback": "长板上的推力小些，可手要推更远。", "id": "b", "misconception": "length-is-height", "text": "变少"}, {"feedback": "坡板虽长，箱子升高的距离没有变。", "id": "c", "misconception": "length-is-height", "text": "变多"}], "type": "choice"}, "feedback": {"correct": "两块板都把同一箱子送上同一层，箱子增加的重力势能相同。", "wrong": "在起点和站台顶各贴一根高度线。"}, "hints": ["在起点和站台顶各贴一根高度线。", "比一比两种路线的终点比起点高多少。"], "id": "q3", "stem": "同一箱子匀速上同一层。有两块光滑坡板。你试过短板，换成长板也沿坡推。手推箱所做的功会怎样？"}, {"answer": {"common_wrong": [{"feedback": "你量的是沿坡走的长度。高度要用竖直的尺量。", "misconception": "length-is-height", "value": 6}], "tolerance": 0, "type": "number", "unit": "米", "value": 2}, "feedback": {"correct": "手做了 6 × 6 = 36 焦的功。箱子每升高一米需要 18 焦，所以升高 2 米。", "wrong": "先读出推力和沿坡走的距离。"}, "hints": ["先读出推力和沿坡走的距离。", "算出手做的功，再除以箱重。"], "id": "q4", "stem": "一箱货重 18 牛。沿光滑坡面用 6 牛的力匀速推了 6 米。站台比起点高几米？"}, {"answer": {"choices": [{"feedback": "这对读数仍按原站台的高度计算。", "id": "a", "misconception": "length-is-height", "text": "4 米板需 3 牛，6 米板需 2 牛"}, {"correct": true, "id": "b", "text": "4 米板需 6 牛，6 米板需 4 牛"}, {"feedback": "同一新高度上，较长的坡板所需推力更小。", "id": "c", "misconception": "length-is-height", "text": "4 米板需 4 牛，6 米板需 6 牛"}], "type": "choice"}, "feedback": {"correct": "新站台需要 12 × 2 = 24 焦。再分别除以 4 米、6 米，得到 6 牛、4 牛。", "wrong": "先把工作票上的站台高度改好。"}, "hints": ["先把工作票上的站台高度改好。", "算出新高度需要的功，再分别摊到两块坡板的长度上。"], "id": "q5", "stem": "箱重 12 牛，原站台高 1 米，新站台高 2 米。新台可搭 4 米或 6 米的光滑坡板。沿坡匀速推，两块板各需几牛？"}], "shuffle": false}, "duration_min": 7, "id": "act.quiz.ramp-dock-01", "kind": "quiz", "targets": ["physics.machine.ramp"], "title": "给货箱搭坡板"}, "act.quiz.work-dock-01": {"age_band": "G3-4", "body": {"items": [{"answer": {"choices": [{"feedback": "磅秤能读出力，还要在尺上找到箱子的移动。", "id": "a", "misconception": "effort-is-work", "text": "按托力有多大来记"}, {"correct": true, "id": "b", "text": "记 0 焦"}, {"feedback": "时间过去了，但箱子仍停在同一条刻线上。", "id": "c", "misconception": "effort-is-work", "text": "托得越久，焦数越多"}], "type": "choice"}, "feedback": {"correct": "箱子的位移为零，所以托力对它做了 0 焦的功。手臂依然可能觉得累。", "wrong": "看看箱子起点和终点的刻线。"}, "hints": ["看看箱子起点和终点的刻线。", "找找箱子在托力方向上走了多远。"], "id": "q1", "stem": "你一直向上托着装书的箱子，箱子停在同一条高度线上。只算托力对箱子做的机械功。工作票该怎么记？"}, {"answer": {"common_wrong": [{"feedback": "你记下了力的大小，还要乘上箱子沿力走过的路。", "misconception": "effort-is-work", "value": 3}], "tolerance": 0, "type": "number", "unit": "焦", "value": 15}, "feedback": {"correct": "每向右走一米，推力做 3 焦的功。走 5 米就是 15 焦。", "wrong": "在纸上标出手推的方向。"}, "hints": ["在纸上标出手推的方向。", "沿这个方向，把每米的功累加起来。"], "id": "q2", "stem": "机器人用 3 牛的恒力向右推箱子。箱子也向右走了 5 米。这股推力对箱子做了几焦的功？"}, {"answer": {"choices": [{"feedback": "小灯的力大一倍，可它推过的路只有一半。", "id": "a", "misconception": "effort-is-work", "text": "小灯更多"}, {"feedback": "小环走的路长一倍，每米用的力却小一半。", "id": "b", "misconception": "effort-is-work", "text": "小环更多"}, {"correct": true, "id": "c", "text": "一样多"}], "type": "choice"}, "feedback": {"correct": "把两张工作票铺开，8 × 2 和 4 × 4 的格子数都是 16。", "wrong": "每张票都要标出推力和同方向的路程。"}, "hints": ["每张票都要标出推力和同方向的路程。", "用两边的乘积比格子总数。"], "id": "q3", "stem": "小灯用 8 牛向右推箱子 2 米，小环用 4 牛向右推同一箱子 4 米。两次力恒定，箱子都向右移动。谁对箱做功更多？"}, {"answer": {"common_wrong": [{"feedback": "水平走的路，不能填在向上托力的距离栏里。", "misconception": "effort-is-work", "value": 45}], "tolerance": 0, "type": "number", "unit": "焦", "value": 18}, "feedback": {"correct": "沿托力方向只升高了 2 米。托力做功为 9 × 2 = 18 焦。", "wrong": "从侧面看托盘起点和终点的高度。"}, "hints": ["从侧面看托盘起点和终点的高度。", "给向上移动的那段盖章，再核对水平方向那段。"], "id": "q4", "stem": "手始终竖直向上托着托盘，托力恒为 9 牛。托盘先升高 2 米，又保持高度水平走了 3 米。托力共做几焦的功？"}, {"answer": {"common_wrong": [{"feedback": "这只够一段的工作票。两段移动都要计入。", "misconception": "effort-is-work", "value": 12}], "tolerance": 0, "type": "number", "unit": "焦", "value": 24}, "feedback": {"correct": "两段各做了 12 焦。挡住后位移为零，合计 12 + 12 = 24 焦。", "wrong": "每当拉力改变，就另开一行工作票。"}, "hints": ["每当拉力改变，就另开一行工作票。", "每行用这段的拉力乘同向位移，再合计。"], "id": "q5", "stem": "拖拉机先向右用 6 牛拉箱子走 2 米，再向右用 4 牛拉它走 3 米，两段拉力各自恒定。最后箱子被挡住，绳仍绷紧。拉力共做几焦的功？"}], "shuffle": false}, "duration_min": 7, "id": "act.quiz.work-dock-01", "kind": "quiz", "targets": ["physics.energy.work"], "title": "给推力开工作票"}, "act.simulation.balance-track-01": {"age_band": "G3-4", "duration_min": 6, "id": "act.simulation.balance-track-01", "kind": "simulation", "src": "../content/activities/act.simulation.balance-track-01/index.html", "targets": ["p.g8.force"], "title": "两根拉绳一辆车"}, "act.simulation.chocolate-split-01": {"age_band": "G3-4", "duration_min": 8, "id": "act.simulation.chocolate-split-01", "kind": "simulation", "src": "../content/activities/act.simulation.chocolate-split-01/index.html", "targets": ["math.operation.distributive-law"], "title": "掰巧克力"}, "act.simulation.energy-dock-01": {"age_band": "G3-4", "duration_min": 6, "id": "act.simulation.energy-dock-01", "kind": "simulation", "src": "../content/activities/act.simulation.energy-dock-01/index.html", "targets": ["physics.energy.transfer"], "title": "滑块能量轨"}, "act.simulation.glide-track-01": {"age_band": "G3-4", "duration_min": 6, "id": "act.simulation.glide-track-01", "kind": "simulation", "src": "../content/activities/act.simulation.glide-track-01/index.html", "targets": ["physics.motion.inertia"], "title": "松手留印轨"}, "act.simulation.lever-dock-01": {"age_band": "G3-4", "duration_min": 7, "id": "act.simulation.lever-dock-01", "kind": "simulation", "src": "../content/activities/act.simulation.lever-dock-01/index.html", "targets": ["physics.machine.lever"], "title": "让粉笔印见光"}, "act.simulation.pair-track-01": {"age_band": "G3-4", "duration_min": 7, "id": "act.simulation.pair-track-01", "kind": "simulation", "src": "../content/activities/act.simulation.pair-track-01/index.html", "targets": ["physics.motion.action-reaction"], "title": "两辆车的互推印章"}, "act.simulation.power-dock-01": {"age_band": "G3-4", "duration_min": 6, "id": "act.simulation.power-dock-01", "kind": "simulation", "src": "../content/activities/act.simulation.power-dock-01/index.html", "targets": ["physics.energy.power"], "title": "并排卷扬台"}, "act.simulation.pulley-dock-01": {"age_band": "G5-6", "duration_min": 7, "id": "act.simulation.pulley-dock-01", "kind": "simulation", "src": "../content/activities/act.simulation.pulley-dock-01/index.html", "targets": ["physics.machine.pulley"], "title": "港口吊箱机"}, "act.simulation.push-track-01": {"age_band": "G3-4", "duration_min": 7, "id": "act.simulation.push-track-01", "kind": "simulation", "src": "../content/activities/act.simulation.push-track-01/index.html", "targets": ["physics.motion.force-acceleration"], "title": "两辆车的测速纸带"}, "act.simulation.ramp-dock-01": {"age_band": "G5-6", "duration_min": 7, "id": "act.simulation.ramp-dock-01", "kind": "simulation", "src": "../content/activities/act.simulation.ramp-dock-01/index.html", "targets": ["physics.machine.ramp"], "title": "伸缩坡板"}, "act.simulation.work-dock-01": {"age_band": "G3-4", "duration_min": 6, "id": "act.simulation.work-dock-01", "kind": "simulation", "src": "../content/activities/act.simulation.work-dock-01/index.html", "targets": ["physics.energy.work"], "title": "做功纸带机"}}, "catalog": {"biology.cell.cell-intro": {"chart_theme": "life", "group": 1, "group_order": 1, "group_title": "生命的说明书", "series": "life-manual", "series_title": "生命的说明书", "star": 1}, "biology.genetics.chromosome-intro": {"chart_theme": "life", "group": 1, "group_order": 3, "group_title": "生命的说明书", "series": "life-manual", "series_title": "生命的说明书", "star": 3}, "biology.genetics.dna-intro": {"chart_theme": "life", "group": 1, "group_order": 2, "group_title": "生命的说明书", "series": "life-manual", "series_title": "生命的说明书", "star": 2}, "math.decimal.compare-add": {"chart_theme": "num", "group": 2, "group_order": 2, "group_title": "小数：把一份再切十份", "series": "zero-to-one", "series_title": "0 和 1 之间", "star": 5}, "math.decimal.point-shift": {"chart_theme": "num", "group": 2, "group_order": 3, "group_title": "小数：把一份再切十份", "series": "zero-to-one", "series_title": "0 和 1 之间", "star": 6}, "math.decimal.tenths": {"chart_theme": "num", "group": 2, "group_order": 1, "group_title": "小数：把一份再切十份", "series": "zero-to-one", "series_title": "0 和 1 之间", "star": 4}, "math.fraction.add-subtract": {"chart_theme": "num", "group": 3, "group_order": 4, "group_title": "一个数，很多名字", "series": "zero-to-one", "series_title": "0 和 1 之间", "star": 10}, "math.fraction.as-division": {"chart_theme": "num", "group": 3, "group_order": 2, "group_title": "一个数，很多名字", "series": "zero-to-one", "series_title": "0 和 1 之间", "star": 8}, "math.fraction.compare": {"chart_theme": "num", "group": 3, "group_order": 3, "group_title": "一个数，很多名字", "series": "zero-to-one", "series_title": "0 和 1 之间", "star": 9}, "math.fraction.count-on-line": {"chart_theme": "num", "group": 1, "group_order": 2, "group_title": "一份有多大", "series": "zero-to-one", "series_title": "0 和 1 之间", "star": 2}, "math.fraction.divide": {"chart_theme": "num", "group": 4, "group_order": 3, "group_title": "乘除的怪事", "series": "zero-to-one", "series_title": "0 和 1 之间", "star": 13}, "math.fraction.equivalent": {"chart_theme": "num", "group": 3, "group_order": 1, "group_title": "一个数，很多名字", "series": "zero-to-one", "series_title": "0 和 1 之间", "star": 7}, "math.fraction.multiply": {"chart_theme": "num", "group": 4, "group_order": 2, "group_title": "乘除的怪事", "series": "zero-to-one", "series_title": "0 和 1 之间", "star": 12}, "math.fraction.the-whole": {"chart_theme": "num", "group": 1, "group_order": 3, "group_title": "一份有多大", "series": "zero-to-one", "series_title": "0 和 1 之间", "star": 3}, "math.fraction.unit-fraction": {"chart_theme": "num", "group": 1, "group_order": 1, "group_title": "一份有多大", "series": "zero-to-one", "series_title": "0 和 1 之间", "star": 1}, "math.number.same-point": {"chart_theme": "num", "group": 6, "group_order": 2, "group_title": "百分数：大家说好的分母", "series": "zero-to-one", "series_title": "0 和 1 之间", "star": 18}, "math.operation.distributive-law": {"chart_theme": "num", "group": 1, "group_order": 1, "group_title": "掰巧克力", "series": "chocolate", "series_title": "乘法的秘密", "star": 1}, "math.operation.multiply-shrinks": {"chart_theme": "num", "group": 4, "group_order": 1, "group_title": "乘除的怪事", "series": "zero-to-one", "series_title": "0 和 1 之间", "star": 11}, "math.percent.change": {"chart_theme": "num", "group": 6, "group_order": 3, "group_title": "百分数：大家说好的分母", "series": "zero-to-one", "series_title": "0 和 1 之间", "star": 19}, "math.percent.meaning": {"chart_theme": "num", "group": 6, "group_order": 1, "group_title": "百分数：大家说好的分母", "series": "zero-to-one", "series_title": "0 和 1 之间", "star": 17}, "math.ratio.meaning": {"chart_theme": "num", "group": 5, "group_order": 1, "group_title": "比：两个量的关系", "series": "zero-to-one", "series_title": "0 和 1 之间", "star": 14}, "math.ratio.proportion": {"chart_theme": "num", "group": 5, "group_order": 3, "group_title": "比：两个量的关系", "series": "zero-to-one", "series_title": "0 和 1 之间", "star": 16}, "math.ratio.sharing": {"chart_theme": "num", "group": 5, "group_order": 2, "group_title": "比：两个量的关系", "series": "zero-to-one", "series_title": "0 和 1 之间", "star": 15}, "p.g8.force": {"chart_theme": "ene", "group": 1, "group_order": 1, "group_title": "先盯一辆车", "series": "newton-track", "series_title": "力怎样改变运动", "star": 1}, "physics.energy.power": {"chart_theme": "ene", "group": 3, "group_order": 1, "group_title": "看秒表，追能量", "series": "energy-dock", "series_title": "省力的机器和能量账本", "star": 5}, "physics.energy.transfer": {"chart_theme": "ene", "group": 3, "group_order": 2, "group_title": "看秒表，追能量", "series": "energy-dock", "series_title": "省力的机器和能量账本", "star": 6}, "physics.energy.work": {"chart_theme": "ene", "group": 2, "group_order": 2, "group_title": "送到同样高", "series": "energy-dock", "series_title": "省力的机器和能量账本", "star": 4}, "physics.machine.lever": {"chart_theme": "ene", "group": 1, "group_order": 1, "group_title": "手里的力", "series": "energy-dock", "series_title": "省力的机器和能量账本", "star": 1}, "physics.machine.pulley": {"chart_theme": "ene", "group": 1, "group_order": 2, "group_title": "手里的力", "series": "energy-dock", "series_title": "省力的机器和能量账本", "star": 2}, "physics.machine.ramp": {"chart_theme": "ene", "group": 2, "group_order": 1, "group_title": "送到同样高", "series": "energy-dock", "series_title": "省力的机器和能量账本", "star": 3}, "physics.motion.action-reaction": {"chart_theme": "ene", "group": 2, "group_order": 2, "group_title": "改变运动，再看伙伴", "series": "newton-track", "series_title": "力怎样改变运动", "star": 4}, "physics.motion.force-acceleration": {"chart_theme": "ene", "group": 2, "group_order": 1, "group_title": "改变运动，再看伙伴", "series": "newton-track", "series_title": "力怎样改变运动", "star": 3}, "physics.motion.inertia": {"chart_theme": "ene", "group": 1, "group_order": 2, "group_title": "先盯一辆车", "series": "newton-track", "series_title": "力怎样改变运动", "star": 2}}, "diagram_series": ["life-manual", "energy-dock", "newton-track"], "figures": {"content/assets/physics.machine.lever/before-release.svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 320 116\" role=\"img\" aria-label=\"松手前，木杆水平。两只砝码各重 2 牛。左钩离木尖一格，右钩离木尖三格。\">\n  <title>松手前的木杆</title>\n  <desc>三角木撑在中间的孔下。沿着等距孔数，左边的砝码挂在一格外，右边的砝码挂在三格外。</desc>\n  <g stroke=\"#1F1E1C\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n    <path fill=\"#EFE4D6\" d=\"M161 40 Q169 62 182 98 Q162 100 138 98 Q149 67 159 40 Z\"/>\n    <path fill=\"none\" stroke-width=\"1.2\" d=\"M153 83 Q154 77 160 67 M161 85 L166 74\"/>\n    <path fill=\"#ECCDB6\" d=\"M24 23 Q71 22 111 23 L296 23 Q300 23 300 27 L299 37 Q299 41 296 41 L24 41 Q20 40 20 36 L20 28 Q20 24 24 23 Z\"/>\n    <g fill=\"#EFE4D6\" stroke-width=\"1.5\">\n      <circle cx=\"46\" cy=\"32\" r=\"3.5\"/>\n      <circle cx=\"84\" cy=\"32\" r=\"3.5\"/>\n      <circle cx=\"122\" cy=\"32\" r=\"3.5\"/>\n      <circle cx=\"160\" cy=\"32\" r=\"3.5\"/>\n      <circle cx=\"198\" cy=\"32\" r=\"3.5\"/>\n      <circle cx=\"236\" cy=\"32\" r=\"3.5\"/>\n      <circle cx=\"274\" cy=\"32\" r=\"3.5\"/>\n    </g>\n    <g id=\"f0-left-weight\">\n      <path fill=\"none\" d=\"M122 32 L122 54 Q122 60 116 61 Q111 61 111 56\"/>\n      <path fill=\"none\" d=\"M111 68 Q110 58 116 58 Q122 57 122 68\"/>\n      <path fill=\"var(--c-sky, #CFDCE6)\" d=\"M100 68 Q113 67 131 68 L135 87 Q135 90 132 90 L99 90 Q96 90 97 87 Z\"/>\n      <text x=\"116\" y=\"84\" font-size=\"14\" font-weight=\"600\" text-anchor=\"middle\" fill=\"var(--ink, #1F1E1C)\" stroke=\"none\">2 牛</text>\n    </g>\n    <use href=\"#f0-left-weight\" transform=\"translate(152 0)\"/>\n  </g>\n</svg>"}, "nodes": [{"activities": ["act.simulation.chocolate-split-01"], "driving_question": "一块巧克力掰成两块，怎么算才一块都不会少？", "grade": "G4", "id": "math.operation.distributive-law", "lenses": [{"approach": "不用字母，用一块排得整整齐齐的巧克力：每排 7 块、5 排，沿着缝掰成每排 3 块和每排 4 块的两块，两块都还是 5 排，所以 (3+4)×5 = 3×5 + 4×5；反过来，排数一样的两块能拼回一整块；再用它口算 12×3 和变「乘 101」的魔术。", "band": "G3-4"}, {"approach": "用字母表示 (a+b)×c = a×c + b×c，正着用、反着用都做简便计算（102×25、38×99、25×37 + 75×37），并和乘法结合律区分开。", "band": "G4-6"}, {"approach": "用面积模型解释去括号和合并同类项，推出 (a+b)(c+d) = ac + ad + bc + bd，说清 12×13 为什么不等于 10×10 + 2×3。", "band": "G7-9"}], "misconceptions": [{"id": "multiply-one-part", "text": "拆开以后只有一部分乘了外面的数，例如把 (3+4)×5 写成 3×5 + 4，把 37×101 算成 37×100 + 1。"}, {"id": "add-instead-of-multiply", "text": "数一整块排好的东西时，把每排几块和有几排加起来，例如每排 4 块、5 排，说成 9 块。"}, {"id": "drop-small-part", "text": "把接近整百的数当成整百来乘，忘了补上多出来的那一点，例如把 37×101 算成 3700。"}, {"id": "merge-unlike", "text": "两个乘法里没有一样的数，也硬合并，例如把 3×5 + 4×6 写成 (3+4)×5。"}, {"id": "split-both", "text": "两个因数都拆开以后只把对应的部分相乘，例如把 12×13 算成 10×10 + 2×3。"}], "objectives": ["知道每排一样多的一整块东西，掰成两块以后，两块加起来还是那么多：(3+4)×5 = 3×5 + 4×5。", "知道掰开以后两块都还有原来那么多排，所以括号里的两个数都要乘 5，不能只乘一个。", "知道反过来也成立：排数一样的两块能拼成一整块，3×5 + 4×5 = (3+4)×5；排数不一样就拼不成一整块，不能这样合起来。", "会把难算的乘法拆成好算的两道：12×3 = 10×3 + 2×3，37×101 = 37×100 + 37×1。", "知道这个规律叫乘法分配律，换成别的数也一样成立。"], "prerequisites": [], "theme": "num", "title": "乘法分配律：掰开来算", "unit": "四年级 · 运算律（旧版人教版在四下第三单元「运算定律」；2026 年秋起的新版放在哪一册，待对照实体书）"}, {"activities": ["act.simulation.lever-dock-01", "act.quiz.lever-dock-01"], "driving_question": "六枚小铁环才和箱子一样重，只挂一枚，能把箱子抬起来吗？", "grade": "G6", "id": "physics.machine.lever", "lenses": [{"approach": "用方印和箱后的粉笔线找出轻环在哪里能抬箱。把两次亲手摆的木杆拓到纸上。", "band": "G3-4"}, {"approach": "保持两端挂钩固定，移动支点；用摆平同一个箱子要挂几牛来比较两种摆法。", "band": "G5-6"}, {"approach": "在水平轻杆上比较两力与各自力臂的乘积，用从水平释放时的转动方向检验推断。", "band": "G7-9"}], "misconceptions": [{"id": "heavy-wins", "text": "箱子比铁环重，不管挂在哪一孔都该是箱子先下沉。"}, {"id": "balance-ceiling", "text": "轻环挪到杆尾最多只能让杆平，抬不起重箱。"}, {"id": "equal-loads", "text": "两边挂得一样重就一定平，挂在哪孔都一样。"}, {"id": "far-wins", "text": "挂得远的那头一定先低，不用看挂了多少。"}, {"id": "pivot-carries-hooks", "text": "移动三角木时，两端的挂钩也跟着走，所以到支点仍一样远。"}, {"id": "wrong-side", "text": "用木尖到箱子的格数代替木尖到左钩的格数。"}, {"id": "overbalances", "text": "能把箱子抬起来的一组，也就能让它停平。"}], "objectives": ["拖动一枚铁环，找出箱底刚好盖住粉笔印和刚刚露出粉笔印的两个相邻挂孔。", "封住两端挂钩，只挪三角木和盘里的砝码，为同一只箱子配出两根平杆。", "在五格木条上指给同伴看支点放在哪、该挂哪枚砝码，并说明换另一对会是哪头低。"], "prerequisites": [], "theme": "ene", "title": "杠杆：把支点挪一格", "unit": "手里的力"}, {"activities": ["act.simulation.pulley-dock-01", "act.quiz.pulley-dock-01"], "driving_question": "都是一个轮子，为什么有的能把手上的力减半？", "grade": "G6", "id": "physics.machine.pulley", "lenses": [{"approach": "先用定滑轮把箱升到刻线，再用动滑轮收同长的绳。自由补收绳，两个箱最后停在同高。", "band": "G3-4"}, {"approach": "忽略轮绳质量和摩擦，匀速；定滑轮一段竖绳承重，动滑轮两段同张力竖绳承重。8 N 箱升 1 m 时输入分别为 8 N×1 m 与 4 N×2 m。", "band": "G7-9"}], "misconceptions": [{"id": "wheel-count", "text": "看轮数不看承重段"}], "objectives": ["忽略轮绳质量和摩擦，匀速；定滑轮一段竖绳承重，动滑轮两段同张力竖绳承重。8 N 箱升 1 m 时输入分别为 8 N×1 m 与 4 N×2 m。", "留下两种绳路在同一高度的手力和绳长。"], "prerequisites": [], "theme": "ene", "title": "滑轮：谁在托箱子", "unit": "手里的力"}, {"activities": ["act.simulation.ramp-dock-01", "act.quiz.ramp-dock-01"], "driving_question": "终点一样高，把坡拉长，手上的力怎么变？", "grade": "G6", "id": "physics.machine.ramp", "lenses": [{"approach": "先选短坡把货升顶，换长板仍对齐同一站台；自选坡长再跑，比较沿坡路程与力。", "band": "G3-4"}, {"approach": "光滑直坡，沿坡匀速推。重12 N的箱升高1 m，坡长2 m需6 N，4 m需3 N。坡长是斜边。", "band": "G7-9"}], "misconceptions": [{"id": "length-is-height", "text": "坡长当高度"}], "objectives": ["光滑直坡，沿坡匀速推。重12 N的箱升高1 m，坡长2 m需6 N，4 m需3 N。坡长是斜边。", "保留两块坡板与同一条站台高度线。"], "prerequisites": [], "theme": "ene", "title": "斜面：长路怎样省力", "unit": "送到同样高"}, {"activities": ["act.simulation.work-dock-01", "act.quiz.work-dock-01"], "driving_question": "力省下了，哪一栏的账补上了？", "grade": "G8", "id": "physics.energy.work", "lenses": [{"approach": "先托住箱不移动，核对箱子的读数；直提和沿理想坡推分别铺出长方形格子，比较格子总数。", "band": "G3-4"}, {"approach": "力恒定且同向时 W=Fs。12 N×1 m和3 N×4 m均为12 J。托静止箱时托力对箱做0 J机械功，人仍会累。", "band": "G7-9"}], "misconceptions": [{"id": "effort-is-work", "text": "用劲就有机械功"}], "objectives": ["力恒定且同向时 W=Fs。12 N×1 m和3 N×4 m均为12 J。托静止箱时托力对箱做0 J机械功，人仍会累。", "两张形状不同、面积相同的工作票。"], "prerequisites": ["physics.machine.ramp"], "theme": "ene", "title": "功：力和路程合起来", "unit": "送到同样高"}, {"activities": ["act.simulation.power-dock-01", "act.quiz.power-dock-01"], "driving_question": "先到站的机器，每秒一定做更多功吗？", "grade": "G8", "id": "physics.energy.power", "lenses": [{"approach": "跑同一单任务改用时；接着给第二台不同货量，两台同时开，比较完成时间和每秒做功。", "band": "G3-4"}, {"approach": "平均功率=W/t；12 J用3 s为4 W，用6 s为2 W。比较不同工作量必须同时看时间。", "band": "G7-9"}], "misconceptions": [{"id": "first-is-powerful", "text": "先完成就功率大"}], "objectives": ["平均功率=W/t；12 J用3 s为4 W，用6 s为2 W。比较不同工作量必须同时看时间。", "两台机器各留一张每秒做功的工票。"], "prerequisites": ["physics.energy.work"], "theme": "ene", "title": "功率：一秒能搬多少", "unit": "看秒表，追能量"}, {"activities": ["act.simulation.energy-dock-01", "act.quiz.energy-dock-01"], "driving_question": "小车停住了，原来那份能量去哪儿了？", "grade": "G8", "id": "physics.energy.transfer", "lenses": [{"approach": "先在不同高度停看势能和动能，再把垫铺在水平轨上；观察滑块停住与仍能数全的十二格。", "band": "G3-4"}, {"approach": "以车、轨道和地球为系统，忽略空气阻力和转动。光滑下坡重力势能减少12 J、动能增加12 J。粗糙水平段动能每少一份，系统内能增加同量（理想化均不传给外界）。", "band": "G7-9"}], "misconceptions": [{"id": "stopped-is-gone", "text": "停下来能量消失"}], "objectives": ["以车、轨道和地球为系统，忽略空气阻力和转动。光滑下坡重力势能减少12 J、动能增加12 J。粗糙水平段动能每少一份，系统内能增加同量（理想化均不传给外界）。", "保存坡顶、坡底、停稳三个时刻的同一本能量账。"], "prerequisites": ["physics.energy.work"], "theme": "ene", "title": "能量：滑停以后去了哪", "unit": "看秒表，追能量"}, {"activities": ["act.simulation.balance-track-01", "act.quiz.balance-track-01"], "driving_question": "左右都挂着砝码，小车一定会改变速度吗？", "grade": "G8", "id": "p.g8.force", "lenses": [{"approach": "先调成两边一样大，再只改一边。用刻线看速度是否变化。", "band": "G3-4"}, {"approach": "同一物体同一直线上的力带方向相加。向右4 N、向左4 N合力0，向右6 N、向左2 N合力向右4 N。", "band": "G7-9"}], "misconceptions": [{"id": "add-both", "text": "只把大小相加"}], "objectives": ["同一物体同一直线上的力带方向相加。向右4 N、向左4 N合力0，向右6 N、向左2 N合力向右4 N。", "一辆车的受力图和合力读数。"], "prerequisites": [], "theme": "ene", "title": "力", "unit": "物理 · 力"}, {"activities": ["act.simulation.glide-track-01", "act.quiz.glide-track-01"], "driving_question": "松开手，同一辆小车为何有时停、有时一直滑？", "grade": "G8", "id": "physics.motion.inertia", "lenses": [{"approach": "先从静止观察，再给车初速度后松手，对照有阻力轨和理想轨的等时印迹。", "band": "G3-4"}, {"approach": "在惯性参考系中合力为零时，静止或匀速直线运动。无阻力直轨模型上已在动的小车每秒走相同距离；普通轨上阻力使它减速。", "band": "G7-9"}], "misconceptions": [{"id": "keep-pushing", "text": "运动必须持续推"}], "objectives": ["在惯性参考系中合力为零时，静止或匀速直线运动。无阻力直轨模型上已在动的小车每秒走相同距离；普通轨上阻力使它减速。", "两条同一时间拍下的轨道足迹。"], "prerequisites": ["p.g8.force"], "theme": "ene", "title": "牛顿第一定律：松手后还会走吗", "unit": "先盯一辆车"}, {"activities": ["act.simulation.push-track-01", "act.quiz.push-track-01"], "driving_question": "更重的车，怎样才能和轻车一起加快？", "grade": "G10", "id": "physics.motion.force-acceleration", "lenses": [{"approach": "同质量换净力，再同净力加货；自己配出两辆加速相同但重量不同的车。", "band": "G3-4"}, {"approach": "恒质量、直线、合力不变时 a=F净/m。2 kg受4 N时2 m/s²；4 kg受4 N时1 m/s²；同时把力和质量加倍时加速度不变。", "band": "G7-9"}], "misconceptions": [{"id": "speed-is-acceleration", "text": "把速度当作加速度"}], "objectives": ["恒质量、直线、合力不变时 a=F净/m。2 kg受4 N时2 m/s²；4 kg受4 N时1 m/s²；同时把力和质量加倍时加速度不变。", "用两张速度随时间增长的纸带给两辆车配对。"], "prerequisites": ["p.g8.force", "physics.motion.inertia"], "theme": "ene", "title": "牛顿第二定律：同一推力推两辆车", "unit": "改变运动，再看伙伴"}, {"activities": ["act.simulation.pair-track-01", "act.quiz.pair-track-01"], "driving_question": "轻车跑得快，是它受到的推力比重车大吗？", "grade": "G10", "id": "physics.motion.action-reaction", "lenses": [{"approach": "让相同质量两车互推；给其中一辆加货，同一瞬间比较两箭头和两辆车速度变化。", "band": "G3-4"}, {"approach": "相互作用的两力同时、等大、反向、分属不同物体。2 kg和4 kg小车互推4 N时加速度大小为2和1 m/s²。水平外力忽略。", "band": "G7-9"}], "misconceptions": [{"id": "cancel-on-one", "text": "反作用力在同一辆车上抵消"}], "objectives": ["相互作用的两力同时、等大、反向、分属不同物体。2 kg和4 kg小车互推4 N时加速度大小为2和1 m/s²。水平外力忽略。", "把两张力签分别贴回受力的那辆车。"], "prerequisites": ["physics.motion.force-acceleration"], "theme": "ene", "title": "牛顿第三定律：两辆车互推", "unit": "改变运动，再看伙伴"}], "overviews": {"m.g4.laws": {"children": ["math.operation.distributive-law"], "text": "交换律、结合律和分配律都属于运算定律。分配律已经可以动手试了。"}, "p.g10.newton": {"children": ["physics.motion.inertia", "physics.motion.force-acceleration", "physics.motion.action-reaction"], "text": "牛顿的三条运动定律，可以一条一条动手试。"}}};
